const SESSION_HOURS = 12;
const MAX_TEXT = 3000;
const IMAGE_MAX = 10 * 1024 * 1024;
const VIDEO_MAX = 50 * 1024 * 1024;
const APP_FIELDS = ["ptype", "orgName", "name", "phone", "email", "area", "age", "job", "qual", "qualDetail", "avail", "knowhow", "motive"];
const MEMBER_FIELDS = ["ptype", "orgName", "name", "phone", "email", "area", "age", "job", "fields", "qual", "qualDetail", "avail", "knowhow", "role", "memberStatus", "memo"];

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone_norm TEXT NOT NULL, pin_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT '대기', data TEXT NOT NULL, admin_note TEXT DEFAULT '', agreed_at INTEGER, submitted_at INTEGER, updated_at INTEGER, decided_at INTEGER)`,
  `CREATE INDEX IF NOT EXISTS idx_app_lookup ON applications(phone_norm, name)`,
  `CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, data TEXT NOT NULL, source TEXT, joined_at INTEGER, updated_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS attempts (kind TEXT NOT NULL, key TEXT NOT NULL, ts INTEGER NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS idx_attempts ON attempts(kind, key, ts)`,
];

let ready = false;
async function ensureDb(env) {
  if (ready) return;
  await env.DB.batch(SCHEMA.map((q) => env.DB.prepare(q)));
  await env.DB.prepare(`INSERT OR IGNORE INTO content (id, data, updated_at) VALUES ('site', ?, ?)`)
    .bind(JSON.stringify(SEED_CONTENT), Date.now()).run();
  ready = true;
}

/* ---------- helpers ---------- */
const json = (data, status = 200, headers = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...headers },
  });
const fail = (status, error, message) => json({ error, message }, status);
const normPhone = (p) => String(p || "").replace(/\D/g, "");
const clip = (v, n = MAX_TEXT) => (typeof v === "string" ? v.slice(0, n).trim() : "");
const enc = new TextEncoder();

async function sha256(s) {
  const b = await crypto.subtle.digest("SHA-256", enc.encode(s));
  return [...new Uint8Array(b)].map((x) => x.toString(16).padStart(2, "0")).join("");
}
function b64url(buf) {
  let s = btoa(String.fromCharCode(...new Uint8Array(buf)));
  return s.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
async function hmac(secret, msg) {
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return b64url(await crypto.subtle.sign("HMAC", key, enc.encode(msg)));
}
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
async function readJson(req) {
  try { return await req.json(); } catch { return null; }
}
function cookie(req, name) {
  const m = (req.headers.get("cookie") || "").match(new RegExp("(?:^|;\\s*)" + name + "=([^;]+)"));
  return m ? m[1] : "";
}
const secretOf = (env) => env.SESSION_SECRET || env.ADMIN_PASSWORD || "";

async function isAdmin(req, env) {
  const tok = cookie(req, "kv_admin");
  if (!tok || !secretOf(env)) return false;
  const [exp, sig] = tok.split(".");
  if (!exp || !sig || Number(exp) < Date.now()) return false;
  return safeEqual(sig, await hmac(secretOf(env), "admin." + exp));
}

async function tooMany(env, kind, key, limit, minutes) {
  const since = Date.now() - minutes * 60000;
  await env.DB.prepare(`DELETE FROM attempts WHERE ts < ?`).bind(Date.now() - 24 * 3600000).run();
  const r = await env.DB.prepare(`SELECT COUNT(*) AS n FROM attempts WHERE kind=? AND key=? AND ts>=?`).bind(kind, key, since).first();
  return (r?.n || 0) >= limit;
}
const logAttempt = (env, kind, key) =>
  env.DB.prepare(`INSERT INTO attempts (kind, key, ts) VALUES (?, ?, ?)`).bind(kind, key, Date.now()).run();

async function getContent(env) {
  const row = await env.DB.prepare(`SELECT data FROM content WHERE id='site'`).first();
  return row ? JSON.parse(row.data) : {};
}
function appOut(row) {
  const d = JSON.parse(row.data);
  return {
    id: row.id, ...d, status: row.status, adminNote: row.admin_note || "",
    agreedAt: row.agreed_at, submittedAt: row.submitted_at, updatedAt: row.updated_at, decidedAt: row.decided_at,
  };
}
function memberOut(row) {
  return { id: row.id, ...JSON.parse(row.data), source: row.source, joinedAt: row.joined_at, updatedAt: row.updated_at };
}
function pickMember(body) {
  const d = {};
  for (const k of MEMBER_FIELDS) {
    if (k === "fields") d.fields = Array.isArray(body.fields) ? body.fields.map((x) => clip(String(x), 100)).filter(Boolean).slice(0, 30) : [];
    else d[k] = clip(body[k] ?? "", k === "memo" || k === "knowhow" ? MAX_TEXT : 300);
  }
  if (!["주민", "지역사회 단체", "기업"].includes(d.ptype)) d.ptype = "주민";
  if (!["활동", "휴면", "탈퇴"].includes(d.memberStatus)) d.memberStatus = "활동";
  return d;
}

/* ---------- public API ---------- */
async function apply(req, env) {
  const b = await readJson(req);
  if (!b) return fail(400, "bad_request", "신청 내용을 읽지 못했어요.");
  const content = await getContent(env);
  if (content.open === "0") return fail(403, "closed", "지금은 신청을 받지 않아요.");

  const d = {};
  for (const k of APP_FIELDS) d[k] = clip(b[k] ?? "", k === "knowhow" || k === "motive" ? MAX_TEXT : 300);
  if (!["주민", "지역사회 단체", "기업"].includes(d.ptype)) d.ptype = "주민";
  const org = d.ptype !== "주민";
  if (!org) d.orgName = ""; else d.age = "";
  const pin = String(b.pin || "");
  const phone = normPhone(d.phone);
  const missing = [];
  if (org && !d.orgName) missing.push("단체·기업 이름");
  if (!d.name) missing.push("이름");
  if (phone.length < 9) missing.push("연락처");
  if (!d.area) missing.push(org ? "소재지" : "사는 곳");
  if (!d.avail) missing.push("함께할 수 있는 정도");
  if (!d.knowhow) missing.push("나눌 수 있는 노하우·전문성·자원");
  if (!/^\d{4}$/.test(pin)) missing.push("조회 비밀번호(숫자 4자리)");
  if (b.agree !== true) missing.push("개인정보 동의");
  if (missing.length) return fail(400, "missing", "확인해 주세요: " + missing.join(", "));

  const ip = req.headers.get("cf-connecting-ip") || "unknown";
  if (await tooMany(env, "apply", ip, 20, 60)) return fail(429, "rate_limited", "짧은 시간에 너무 많이 제출했어요. 잠시 뒤 다시 시도해 주세요.");
  await logAttempt(env, "apply", ip);

  const now = Date.now();
  const existing = await env.DB.prepare(`SELECT * FROM applications WHERE phone_norm=? AND name=? ORDER BY submitted_at DESC LIMIT 1`).bind(phone, d.name).first();
  if (existing) {
    if (!safeEqual(existing.pin_hash, await sha256(existing.id + ":" + pin)))
      return fail(409, "exists", "같은 이름과 연락처로 낸 신청서가 이미 있어요. 처음 정한 조회 비밀번호를 적어야 고칠 수 있어요.");
    if (existing.status === "승인") return fail(409, "approved", "이미 승인된 신청이에요. 바꿀 내용은 담당자에게 연락해 주세요.");
    const keepDate = existing.status === "대기" ? existing.submitted_at : now;
    await env.DB.prepare(`UPDATE applications SET data=?, status='대기', admin_note='', agreed_at=?, submitted_at=?, updated_at=?, decided_at=NULL WHERE id=?`)
      .bind(JSON.stringify(d), now, keepDate, now, existing.id).run();
    return json({ ok: true, updated: true, status: "대기", submittedAt: keepDate });
  }
  const id = crypto.randomUUID();
  await env.DB.prepare(`INSERT INTO applications (id, name, phone_norm, pin_hash, status, data, admin_note, agreed_at, submitted_at, updated_at) VALUES (?, ?, ?, ?, '대기', ?, '', ?, ?, ?)`)
    .bind(id, d.name, phone, await sha256(id + ":" + pin), JSON.stringify(d), now, now, now).run();
  return json({ ok: true, updated: false, status: "대기", submittedAt: now });
}

async function lookup(req, env) {
  const b = await readJson(req);
  const name = clip(b?.name || "", 300), phone = normPhone(b?.phone), pin = String(b?.pin || "");
  if (!name || phone.length < 9 || !/^\d{4}$/.test(pin)) return fail(400, "bad_request", "이름, 연락처, 비밀번호 4자리를 모두 적어 주세요.");
  if (await tooMany(env, "lookup", phone, 5, 15)) return fail(429, "rate_limited", "여러 번 틀려서 잠시 조회가 막혔어요. 15분 뒤 다시 시도하거나 담당자에게 연락해 주세요.");
  const row = await env.DB.prepare(`SELECT * FROM applications WHERE phone_norm=? AND name=? ORDER BY submitted_at DESC LIMIT 1`).bind(phone, name).first();
  if (!row || !safeEqual(row.pin_hash, await sha256(row.id + ":" + pin))) {
    await logAttempt(env, "lookup", phone);
    return fail(404, "not_found", "일치하는 신청 내역이 없어요. 이름, 연락처, 비밀번호를 다시 확인해 주세요.");
  }
  const a = appOut(row);
  if (a.status !== "반려") a.adminNote = "";
  delete a.id;
  return json(a);
}

/* ---------- admin API ---------- */
async function login(req, env) {
  if (!env.ADMIN_PASSWORD) return fail(500, "not_configured", "관리자 비밀번호가 아직 설정되지 않았어요. 배포 안내서의 ADMIN_PASSWORD 설정을 확인해 주세요.");
  const ip = req.headers.get("cf-connecting-ip") || "unknown";
  if (await tooMany(env, "login", ip, 10, 15)) return fail(429, "rate_limited", "여러 번 틀려서 잠시 로그인이 막혔어요. 15분 뒤 다시 시도해 주세요.");
  const b = await readJson(req);
  const ok = safeEqual(await sha256(String(b?.password || "")), await sha256(env.ADMIN_PASSWORD));
  if (!ok) {
    await logAttempt(env, "login", ip);
    return fail(401, "wrong_password", "비밀번호가 맞지 않아요.");
  }
  const exp = Date.now() + SESSION_HOURS * 3600000;
  const tok = exp + "." + (await hmac(secretOf(env), "admin." + exp));
  return json({ ok: true }, 200, {
    "set-cookie": `kv_admin=${tok}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${SESSION_HOURS * 3600}`,
  });
}

async function adminRoute(req, env, url, path) {
  const m = req.method;
  if (path === "/api/admin/content" && m === "PUT") {
    const b = await readJson(req);
    if (!b || typeof b !== "object" || Array.isArray(b)) return fail(400, "bad_request", "저장할 내용을 읽지 못했어요.");
    const text = JSON.stringify(b);
    if (text.length > 400000) return fail(413, "too_large", "내용이 너무 길어요.");
    await env.DB.prepare(`INSERT INTO content (id, data, updated_at) VALUES ('site', ?, ?) ON CONFLICT(id) DO UPDATE SET data=excluded.data, updated_at=excluded.updated_at`)
      .bind(text, Date.now()).run();
    return json({ ok: true });
  }
  if (path === "/api/admin/applications" && m === "GET") {
    const { results } = await env.DB.prepare(`SELECT * FROM applications ORDER BY submitted_at DESC`).all();
    return json(results.map(appOut));
  }
  let r = path.match(/^\/api\/admin\/applications\/([\w-]+)(\/approve)?$/);
  if (r) {
    const id = r[1];
    const row = await env.DB.prepare(`SELECT * FROM applications WHERE id=?`).bind(id).first();
    if (!row) return fail(404, "not_found", "신청서를 찾지 못했어요.");
    const b = (await readJson(req)) || {};
    if (r[2] && m === "POST") {
      const a = appOut(row), now = Date.now();
      const old = await env.DB.prepare(`SELECT * FROM members WHERE id=?`).bind(id).first();
      const prev = old ? JSON.parse(old.data) : {};
      const mem = pickMember({
        ...a, fields: prev.fields || [], role: prev.role || clip(b.role || "일반회원", 100),
        memberStatus: prev.memberStatus || "활동", memo: prev.memo || "",
      });
      await env.DB.batch([
        env.DB.prepare(`INSERT INTO members (id, data, source, joined_at, updated_at) VALUES (?, ?, '신청서', ?, ?) ON CONFLICT(id) DO UPDATE SET data=excluded.data, updated_at=excluded.updated_at`)
          .bind(id, JSON.stringify(mem), old?.joined_at || now, now),
        env.DB.prepare(`UPDATE applications SET status='승인', admin_note=?, decided_at=? WHERE id=?`).bind(clip(b.adminNote || ""), now, id),
      ]);
      return json({ ok: true });
    }
    if (!r[2] && m === "PATCH") {
      const status = ["대기", "반려"].includes(b.status) ? b.status : null;
      if (!status) return fail(400, "bad_request", "바꿀 상태가 올바르지 않아요.");
      await env.DB.prepare(`UPDATE applications SET status=?, admin_note=?, decided_at=? WHERE id=?`)
        .bind(status, clip(b.adminNote || ""), status === "대기" ? null : Date.now(), id).run();
      return json({ ok: true });
    }
    if (!r[2] && m === "DELETE") {
      await env.DB.prepare(`DELETE FROM applications WHERE id=?`).bind(id).run();
      return json({ ok: true });
    }
  }
  if (path === "/api/admin/members" && m === "GET") {
    const { results } = await env.DB.prepare(`SELECT * FROM members ORDER BY joined_at DESC`).all();
    return json(results.map(memberOut));
  }
  if (path === "/api/admin/members" && m === "POST") {
    const d = pickMember((await readJson(req)) || {});
    if (!d.name) return fail(400, "missing", "이름을 적어 주세요.");
    const id = crypto.randomUUID(), now = Date.now();
    await env.DB.prepare(`INSERT INTO members (id, data, source, joined_at, updated_at) VALUES (?, ?, '직접 추가', ?, ?)`).bind(id, JSON.stringify(d), now, now).run();
    return json({ ok: true, id });
  }
  r = path.match(/^\/api\/admin\/members\/([\w-]+)$/);
  if (r) {
    const row = await env.DB.prepare(`SELECT * FROM members WHERE id=?`).bind(r[1]).first();
    if (!row) return fail(404, "not_found", "회원을 찾지 못했어요.");
    if (m === "PATCH") {
      const d = pickMember({ ...JSON.parse(row.data), ...((await readJson(req)) || {}) });
      if (!d.name) return fail(400, "missing", "이름을 적어 주세요.");
      await env.DB.prepare(`UPDATE members SET data=?, updated_at=? WHERE id=?`).bind(JSON.stringify(d), Date.now(), r[1]).run();
      return json({ ok: true });
    }
    if (m === "DELETE") {
      await env.DB.prepare(`DELETE FROM members WHERE id=?`).bind(r[1]).run();
      return json({ ok: true });
    }
  }
  if (path === "/api/admin/upload" && m === "POST") {
    if (!env.FILES) return fail(500, "not_configured", "파일 저장소(R2)가 연결되지 않았어요.");
    const form = await req.formData().catch(() => null);
    const f = form && form.get("file");
    if (!f || typeof f === "string") return fail(400, "bad_request", "올릴 파일을 찾지 못했어요.");
    const type = f.type || "";
    const isImg = /^image\/(png|jpeg|webp|gif)$/.test(type), isVid = /^video\/(mp4|webm)$/.test(type);
    if (!isImg && !isVid) return fail(415, "unsupported_type", "이미지(png, jpg, webp, gif)나 영상(mp4, webm)만 올릴 수 있어요.");
    if (f.size > (isImg ? IMAGE_MAX : VIDEO_MAX)) return fail(413, "too_large", isImg ? "이미지는 10MB 이하로 올려 주세요." : "영상은 50MB 이하로 올려 주세요.");
    const ext = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/gif": "gif", "video/mp4": "mp4", "video/webm": "webm" }[type];
    const key = crypto.randomUUID() + "." + ext;
    await env.FILES.put(key, f.stream(), { httpMetadata: { contentType: type } });
    return json({ ok: true, key });
  }
  r = path.match(/^\/api\/admin\/files\/([\w.-]+)$/);
  if (r && m === "DELETE") {
    if (env.FILES) await env.FILES.delete(r[1]);
    return json({ ok: true });
  }
  return fail(404, "not_found", "없는 주소예요.");
}

async function serveFile(req, env, key) {
  if (!env.FILES || !/^[\w.-]+$/.test(key)) return new Response("Not found", { status: 404 });
  const obj = await env.FILES.get(key, { range: req.headers, onlyIf: req.headers });
  if (!obj) return new Response("Not found", { status: 404 });
  const h = new Headers();
  obj.writeHttpMetadata(h);
  h.set("etag", obj.httpEtag);
  h.set("cache-control", "public, max-age=31536000, immutable");
  h.set("accept-ranges", "bytes");
  if (!("body" in obj) || !obj.body) return new Response(null, { status: 304, headers: h });
  if (obj.range && req.headers.has("range")) {
    const { offset = 0, length = obj.size - offset } = obj.range;
    h.set("content-range", `bytes ${offset}-${offset + length - 1}/${obj.size}`);
    h.set("content-length", String(length));
    return new Response(obj.body, { status: 206, headers: h });
  }
  return new Response(obj.body, { headers: h });
}

function page() {
  return new Response(HTML, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-cache",
      "x-content-type-options": "nosniff",
      "referrer-policy": "strict-origin-when-cross-origin",
      "x-frame-options": "SAMEORIGIN",
    },
  });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const path = url.pathname;
    try {
      if (path.startsWith("/files/")) return await serveFile(req, env, decodeURIComponent(path.slice(7)));
      if (!path.startsWith("/api/")) return page();
      if (!env.DB) return fail(500, "not_configured", "데이터베이스(D1)가 연결되지 않았어요.");
      await ensureDb(env);

      // 다른 사이트에서 보낸 요청 막기
      if (req.method !== "GET") {
        const origin = req.headers.get("origin");
        if (origin && origin !== url.origin) return fail(403, "bad_origin", "허용되지 않은 요청이에요.");
      }

      if (path === "/api/content" && req.method === "GET") return json(await getContent(env));
      if (path === "/api/apply" && req.method === "POST") return await apply(req, env);
      if (path === "/api/lookup" && req.method === "POST") return await lookup(req, env);
      if (path === "/api/admin/login" && req.method === "POST") return await login(req, env);
      if (path === "/api/admin/logout" && req.method === "POST")
        return json({ ok: true }, 200, { "set-cookie": "kv_admin=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0" });
      if (path === "/api/admin/me") return json({ admin: await isAdmin(req, env) });
      if (path.startsWith("/api/admin/")) {
        if (!(await isAdmin(req, env))) return fail(401, "unauthorized", "관리자 로그인이 필요해요.");
        return await adminRoute(req, env, url, path);
      }
      return fail(404, "not_found", "없는 주소예요.");
    } catch (e) {
      return fail(500, "server_error", "서버에서 문제가 생겼어요. 잠시 뒤 다시 시도해 주세요.");
    }
  },
};
